const big = 100010;

function gen_mu() {
    const mu = new Array(big).fill(1);
    mu[0] = 0;
    const P = new Array(big).fill(true);
    P[0] = false;
    P[1] = false;
    for (let i = 2; i < big; i++) {
        if (P[i]) {
            let j = i;
            while (j < big) {
                P[j] = false;
                mu[j] *= -1;
                j += i;
            }
            j = i * i;
            while (j < big) {
                mu[j] = 0;
                j += i * i;
            }
        }
    }
    return mu;
}

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim();
const m = parseInt(input, 10);

const mu = gen_mu();

const MOD = 1000000007n;

function modPow(base, exp, mod) {
    base = ((base % mod) + mod) % mod;
    let result = 1n;
    while (exp > 0n) {
        if (exp & 1n) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1n;
    }
    return result;
}

function modInv(x) {
    return modPow(BigInt(x), MOD - 2n, MOD);
}

let s = 1n;
const mBig = BigInt(m);
const invM = modInv(mBig);

for (let i = 2; i < big; i++) {
    const muVal = BigInt(-mu[i]);
    const p = (BigInt(Math.floor(m / i)) * invM) % MOD;
    const oneMinusP = (1n - p + MOD) % MOD;
    const invOneMinusP = modInv(oneMinusP);
    const term = (((muVal * p) % MOD) * invOneMinusP) % MOD;
    s = (s + term) % MOD;
}

console.log(((s % MOD) + MOD) % MOD);

